mapper.select:
select row_number() over() as rId, ri.report_name reportName, case when re.START_DATE is null then to_char(re.END_DATE,'yyyy-MM-dd') ELSE to_char(re.START_DATE,'yyyy-MM-dd')||'-'||to_char(re.END_DATE,'yyyy-MM-dd') end reportDate, re.INDEX_ID indexId, re.INDEX_VALUE indexValue, re.PROD_ID prodId, re.PROD_NAME prodName, re.PROD_VALUE prodValue, re.ERRORMSG errormsg from REP_CHECK_ERRMSG re left join rep_info ri on re.rep_id=ri.rep_id where 1=1
and ri.report_name=#{reportName}
and to_char(re.CREATE_TIME,'yyyy-MM-dd')<#{endDate}
and to_char(re.CREATE_TIME,'yyyy-MM-dd')>#{startDate}
AND re.prod_id IN
#{item}

select row_number() over() as rId, ri.report_name reportName, case when re.START_DATE is null then to_char(re.END_DATE,'yyyy-MM-dd') ELSE to_char(re.START_DATE,'yyyy-MM-dd')||' - '||to_char(re.END_DATE,'yyyy-MM-dd') end reportDate, re.INDEX_ID indexId, re.INDEX_VALUE indexValue, re.PROD_ID prodId, re.PROD_NAME prodName, re.PROD_VALUE prodValue, re.ERRORMSG errormsg from REP_CHECK_ERRMSG re left join rep_info ri on re.rep_id=ri.rep_id where 1=1
and re.INDEX_ID=#{reportName}
and to_char(re.CREATE_TIME,'yyyy-MM-dd')<#{endDate}
and to_char(re.CREATE_TIME,'yyyy-MM-dd')>#{startDate}
AND re.prod_id IN
#{item}
